package com.akhil.portfolio.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.util.Date; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtService { private final byte[] key; private final long exp; public JwtService(@Value("${app.jwt-secret}")String s,@Value("${app.jwt-expiration-ms}")long e){key=s.getBytes(StandardCharsets.UTF_8);exp=e;} public String create(String user){Date n=new Date();return Jwts.builder().subject(user).issuedAt(n).expiration(new Date(n.getTime()+exp)).signWith(Keys.hmacShaKeyFor(key)).compact();} public String subject(String token){return Jwts.parser().verifyWith(Keys.hmacShaKeyFor(key)).build().parseSignedClaims(token).getPayload().getSubject();}}